    }

    /**
     * Get master commission for a ledger between two dates
     */
    public function get_master_commission_reportoldd($ledger_id, $start_date, $end_date) {
        $start_datetime = date('Y-m-d 12:00:00', strtotime($start_date));
        $end_datetime   = date('Y-m-d 06:00:00', strtotime($end_date . ' +1 day'));

        $sql = "
            SELECT 
                DATE(mt.t_date) AS report_date,
                SUM(mt.total_number_amount) AS total_number_amount,
                SUM(mt.total_akhar_amount) AS total_akhar_amount,
                l.dara__master_commision,
                l.akhar__master_commision,
                (
                    (SUM(mt.total_number_amount) * (CAST(l.dara__master_commision AS DECIMAL(10,2)) / 100)) +
                    (SUM(mt.total_akhar_amount) * (CAST(l.akhar__master_commision AS DECIMAL(10,2)) / 100))
                ) AS master_commission
            FROM tbl_master_transaction mt
            INNER JOIN tbl_ledger l ON mt.party_id = l.id
            WHERE mt.party_id = ?
              AND mt.t_date BETWEEN ? AND ?
            GROUP BY report_date
            ORDER BY report_date ASC
        ";
//   // 👇 Build final query string manually for debugging
//     $final_query = $this->db->compile_binds($sql, [$ledger_id, $start_datetime, $end_datetime]);

//     echo "<pre>$final_query</pre>"; // Debug print
//     die;
        return $this->db->query($sql, [$ledger_id, $start_datetime, $end_datetime])->result_array();
    }
public function get_master_commission_report($ledger_id, $start_date, $end_date)
{
    $start_datetime = date('Y-m-d 06:00:00', strtotime($start_date));
    $end_datetime   = date('Y-m-d 06:00:00', strtotime($end_date . ' +1 day'));

    $sql = "
        SELECT 
            DATE(DATE_SUB(mt.t_date, INTERVAL 6 HOUR)) AS report_date,
            SUM(mt.total_number_amount) AS total_number_amount,
            SUM(mt.total_akhar_amount) AS total_akhar_amount,
            l.dara__master_commision,
            l.akhar__master_commision,
            (
                (SUM(mt.total_number_amount) * (CAST(l.dara__master_commision AS DECIMAL(10,2)) / 100)) +
                (SUM(mt.total_akhar_amount) * (CAST(l.akhar__master_commision AS DECIMAL(10,2)) / 100))
            ) AS master_commission
        FROM tbl_master_transaction mt
        INNER JOIN tbl_ledger l ON mt.party_id = l.id
        WHERE mt.party_id = ?
          AND mt.t_date >= ?
          AND mt.t_date < ?
        GROUP BY DATE(DATE_SUB(mt.t_date, INTERVAL 6 HOUR))
        ORDER BY DATE(DATE_SUB(mt.t_date, INTERVAL 6 HOUR)) ASC
    ";

    return $this->db->query($sql, [$ledger_id, $start_datetime, $end_datetime])->result_array();
}
