    public function getledgercreditdebit_with_coin_balance()
{
    $admin_id = $this->session->userdata('id');

    /*
     * Same date range as get_final_balance()
     */
    $start_date = '2025-08-01';
    $end_date   = date('Y-m-d');

    $start_datetime = date('Y-m-d H:i:s', strtotime($start_date . ' 12:00:00'));
    $end_datetime   = date('Y-m-d H:i:s', strtotime($end_date . ' +1 day 06:00:00'));

    $hisab_start_date = date('Y-m-d', strtotime($start_datetime));
    $hisab_end_date   = date('Y-m-d', strtotime($end_datetime));

    /*
     * Latest transaction date per ledger
     */
    $sub_transaction = "(
        SELECT 
            party_id, 
            MAX(t_date) AS latest_transaction_date 
        FROM tbl_master_transaction 
        GROUP BY party_id
    ) AS mt";

    /*
     * Latest credit balance per ledger
     */
    $sub_credit = "(
        SELECT 
            c1.party_id, 
            c1.credit_balance
        FROM tbl_credit c1
        INNER JOIN (
            SELECT 
                party_id, 
                MAX(id) AS max_id
            FROM tbl_credit
            GROUP BY party_id
        ) c2 ON c1.party_id = c2.party_id 
            AND c1.id = c2.max_id
    ) AS cr";

    /*
     * Latest hisab row per ledger
     */
    $sub_hisab = "(
        SELECT 
            h1.ledger_id, 
            h1.final_hisab, 
            h1.today_hisab
        FROM tbl_final_hisab h1
        INNER JOIN (
            SELECT 
                ledger_id, 
                MAX(id) AS max_id
            FROM tbl_final_hisab
            GROUP BY ledger_id
        ) h2 ON h1.ledger_id = h2.ledger_id 
            AND h1.id = h2.max_id
    ) AS h";

    /*
     * Main ledger query
     */
    $this->db->select("
        l.id AS ledger_id,
        l.ledger_name,
         l.username,
        l.password,
        l.openingbalance,
        IFNULL(cr.credit_balance, 0) AS credit_balance,
        IFNULL(h.final_hisab, 0) AS final_hisab,
        IFNULL(h.today_hisab, 0) AS today_hisab,
        mt.latest_transaction_date AS last_transaction_date
    ", false);

    $this->db->from('tbl_ledger l');
    $this->db->join($sub_credit, 'l.id = cr.party_id', 'left');
    $this->db->join($sub_transaction, 'l.id = mt.party_id', 'left');
    $this->db->join($sub_hisab, 'l.id = h.ledger_id', 'left');

    $this->db->where('l.updated_by', $admin_id);

    /*
     * Old function did not filter status.
     * Keep this commented if you want exact old output.
     * Uncomment only if inactive ledgers should be excluded.
     */
    // $this->db->where('l.status', 1);

    $this->db->group_by('l.id');
    $this->db->order_by('l.ledger_name', 'ASC');

    $results = $this->db->get()->result_array();

    $ledger_ids = array_column($results, 'ledger_id');

    if (empty($ledger_ids)) {
        return [];
    }

    /*
     * 1. Coins received
     *
     * Exact get_final_balance() rule:
     * If receiver_id == ledger_id, add amount.
     * No status filter is used for received coins in helper.
     */
    $this->db->select('receiver_id AS ledger_id, COALESCE(SUM(amount), 0) AS received_amount', false);
    $this->db->from('coin_transactions');
    $this->db->where_in('receiver_id', $ledger_ids);
    $this->db->where('created_at >=', $start_datetime);
    $this->db->where('created_at <', $end_datetime);
    $this->db->group_by('receiver_id');

    $received_rows = $this->db->get()->result_array();
    $received_map = array_column($received_rows, 'received_amount', 'ledger_id');

    /*
     * 2. Coins sent / spent
     *
     * Exact get_final_balance() rule:
     * sender_id == ledger_id
     * type = spend
     * status = 1
     */
    $this->db->select('sender_id AS ledger_id, COALESCE(SUM(amount), 0) AS sent_amount', false);
    $this->db->from('coin_transactions');
    $this->db->where_in('sender_id', $ledger_ids);
    $this->db->where('type', 'spend');
    $this->db->where('status', 1);
    $this->db->where('created_at >=', $start_datetime);
    $this->db->where('created_at <', $end_datetime);
    $this->db->group_by('sender_id');

    $sent_rows = $this->db->get()->result_array();
    $sent_map = array_column($sent_rows, 'sent_amount', 'ledger_id');

    /*
     * 3. P/L from tbl_final_hisab
     *
     * Helper logic:
     *
     * if today_hisab < 0:
     *     balance += abs(today_hisab)
     * else:
     *     balance -= today_hisab
     *
     * This is mathematically same as:
     * balance -= today_hisab
     *
     * Example:
     * today_hisab = 100  => balance - 100
     * today_hisab = -100 => balance - (-100) = balance + 100
     */
    $this->db->select('ledger_id, COALESCE(SUM(today_hisab), 0) AS hisab_amount', false);
    $this->db->from('tbl_final_hisab');
    $this->db->where_in('ledger_id', $ledger_ids);
    $this->db->where("STR_TO_DATE(`date`, '%d-%m-%Y') >=", $hisab_start_date);
    $this->db->where("STR_TO_DATE(`date`, '%d-%m-%Y') <", $hisab_end_date);
    $this->db->group_by('ledger_id');

    $hisab_rows = $this->db->get()->result_array();
    $hisab_map = array_column($hisab_rows, 'hisab_amount', 'ledger_id');

    /*
     * 4. Final balance
     *
     * Same as get_final_balance():
     * balance = received - sent - today_hisab
     */
    foreach ($results as &$row) {
        $ledger_id = $row['ledger_id'];

        $received_amount = isset($received_map[$ledger_id]) ? (float) $received_map[$ledger_id] : 0;
        $sent_amount     = isset($sent_map[$ledger_id]) ? (float) $sent_map[$ledger_id] : 0;
        $hisab_amount    = isset($hisab_map[$ledger_id]) ? (float) $hisab_map[$ledger_id] : 0;

        $row['coin_balance'] = $received_amount - $sent_amount - $hisab_amount;
    }

    unset($row);

    return $results;
}
    public function getledgercreditdebit_with_coin_balanceold()
    {
        $admin_id = $this->session->userdata('id');

        // Subqueries (same as before)
        $sub_transaction = "(SELECT party_id, MAX(t_date) AS latest_transaction_date 
                         FROM tbl_master_transaction 
                         GROUP BY party_id) AS mt";

        $sub_credit = "(SELECT c1.*
                    FROM tbl_credit c1
                    INNER JOIN (
                        SELECT party_id, MAX(id) AS max_id
                        FROM tbl_credit
                        GROUP BY party_id
                    ) c2 ON c1.party_id = c2.party_id AND c1.id = c2.max_id
                  ) AS cr";

        $sub_hisab = "(SELECT h1.*
                   FROM tbl_final_hisab h1
                   INNER JOIN (
                       SELECT ledger_id, MAX(id) AS max_id
                       FROM tbl_final_hisab
                       GROUP BY ledger_id 
                   ) h2 ON h1.ledger_id = h2.ledger_id AND h1.id = h2.max_id
                  ) AS h";

        // Main Ledger Query
        $this->db->select("
        l.id AS ledger_id,
        l.ledger_name,
        l.openingbalance,
        IFNULL(cr.credit_balance, 0) AS credit_balance,
        IFNULL(h.final_hisab, 0) AS final_hisab,
        IFNULL(h.today_hisab, 0) AS today_hisab,
       
        IFNULL(mt.latest_transaction_date, NULL) AS last_transaction_date
    ");

        $this->db->from('tbl_ledger l');
        $this->db->join($sub_credit, 'l.id = cr.party_id', 'left');
        $this->db->join($sub_transaction, 'l.id = mt.party_id', 'left');
        $this->db->join($sub_hisab, 'l.id = h.ledger_id', 'left');
        $this->db->where('l.updated_by', $admin_id);
        $this->db->group_by('l.id');
        $this->db->order_by('l.ledger_name', 'ASC');

        $query = $this->db->get();
        $results = $query->result_array();

        // Prepare ledger IDs
        $ledger_ids = array_column($results, 'ledger_id');
        if (empty($ledger_ids)) {
            return [];
        }

        // 1. Used coins this month from tbl_final_hisab
        $this->db->select('ledger_id, SUM(today_hisab) as used_amount');
        $this->db->from('tbl_final_hisab');
        $this->db->where_in('ledger_id', $ledger_ids);
        $this->db->where("STR_TO_DATE(date, '%d-%m-%Y') BETWEEN DATE_FORMAT(CURDATE(), '%Y-%m-01') AND LAST_DAY(CURDATE())", null, false);
        $this->db->group_by('ledger_id');
        $used = $this->db->get()->result_array();
        $used_map = array_column($used, 'used_amount', 'ledger_id');

        // 2. Coins received
        $this->db->select('receiver_id, SUM(amount) as received');
        $this->db->from('coin_transactions');
        $this->db->where_in('receiver_id', $ledger_ids);
        $this->db->group_by('receiver_id');
        $received = $this->db->get()->result_array();
        $received_map = array_column($received, 'received', 'receiver_id');

        // 3. Coins sent today after 6:00 AM
        $this->db->select('sender_id, SUM(amount) as sent');
        $this->db->from('coin_transactions');
        $this->db->where_in('sender_id', $ledger_ids);
        $this->db->where('status', 1);
        $this->db->where("created_at >= CONCAT(CURDATE(), ' 06:00:00')", null, false);
        $this->db->group_by('sender_id');
        $sent = $this->db->get()->result_array();
        $sent_map = array_column($sent, 'sent', 'sender_id');
        $this->load->helper('comman');
        // Final map assignment
        foreach ($results as &$row) {
            // $id = $row['ledger_id'];
            // $coin_received = isset($received_map[$id]) ? (float) $received_map[$id] : 0;
            // $coin_sent     = isset($sent_map[$id]) ? (float) $sent_map[$id] : 0;
            // $coin_used     = isset($used_map[$id]) ? (float) $used_map[$id] : 0;
            // if($id==409){
            // //echo $coin_received .' '. $coin_sent .' '. $coin_used.'<br>'; 
            // }
            // $row['coin_balance'] = $coin_received - $coin_sent - $coin_used;
            $ledger_id = $row['ledger_id'];
            $start_date = '2025-08-01'; // First of current month
            $end_date = date('Y-m-d');    // Today

            $row['coin_balance'] = get_final_balance($this, $ledger_id, $start_date, $end_date);
        }

        return $results;
    }



