    public function get_coin_balance($login_id)
    {
        // 1. Total coins used this month from tbl_final_hisab
        $this->db->select('SUM(today_hisab) as amount');
        $this->db->from('tbl_final_hisab');
        $this->db->where('ledger_id', $login_id);
        $this->db->where("STR_TO_DATE(date, '%d-%m-%Y') BETWEEN DATE_FORMAT(CURDATE(), '%Y-%m-01') AND LAST_DAY(CURDATE())", null, false);
        $used_result = $this->db->get()->row();
        $used_amount = $used_result && $used_result->amount ? (float) $used_result->amount : 0;

        // 2. Total coins received
        $this->db->select('SUM(amount) as coin_balance');
        $this->db->from('coin_transactions');
        $this->db->where('receiver_id', $login_id);
        $received_result = $this->db->get()->row();
        $coin_received = $received_result && $received_result->coin_balance ? (float) $received_result->coin_balance : 0;

        // 3. Total coins sent after today 6:00 AM
        $this->db->select('SUM(amount) as amount');
        $this->db->from('coin_transactions');
        $this->db->where('sender_id', $login_id);
        $this->db->where('status', 1);
        $this->db->where("created_at >= CONCAT(CURDATE(), ' 06:00:00')", null, false);
        $sent_result = $this->db->get()->row();
        $coin_sent = $sent_result && $sent_result->amount ? (float) $sent_result->amount : 0;

        // Final coin balance = Received - Sent - Used
        return $coin_received - $coin_sent - $used_amount;
    }


    public function getLedgerTotalBalance($ledger_id)
    {
        // Get the latest credit record for this ledger
        $this->db->select('credit_balance');
        $this->db->from('tbl_credit');
        $this->db->where('party_id', $ledger_id);
        $this->db->order_by('id', 'desc');
        $this->db->limit(1);

        $creditQuery = $this->db->get();
        $creditResult = $creditQuery->row();

        $credit_balance = $creditResult ? $creditResult->credit_balance : 0;

        // Get the final hisab (profit/loss) for this ledger
        $this->db->select('final_hisab');
        $this->db->from('tbl_final_hisab');
        $this->db->where('ledger_id', $ledger_id);
        $hisabQuery = $this->db->get();
        $hisabResult = $hisabQuery->row();

        $final_hisab = $hisabResult ? $hisabResult->final_hisab : 0;

        // Calculate total balance
        $totalbalance = $credit_balance - $final_hisab;

        return $totalbalance;
    }


    public function getledgercreditdebitback()
    {
        $month_start = date('Y-m-01');
        $month_end = date('Y-m-t');
        $admin_id = $this->session->userdata['id'];

        $this->db->select("
        l.id as ledger_id,
        l.ledger_name AS account_name,
        ct.created_at AS transaction_date,
        CASE 
            WHEN ct.receiver_id = l.id THEN ct.amount 
            ELSE 0 
        END AS credit,
        CASE 
            WHEN ct.sender_id = l.id THEN ct.amount 
            ELSE 0 
        END AS withdraw,
        IFNULL(tc.credit_balance, 0) AS party_credit,
        (l.openingbalance + l.coin_balance) AS totalbalance
    ", false);

        $this->db->from('coin_transactions ct');
        $this->db->join('tbl_ledger l', 'l.id = ct.sender_id OR l.id = ct.receiver_id');
        $this->db->join('tbl_credit tc', 'tc.party_id = l.id', 'left'); // Left join to get credit or 0 if not found
        $this->db->where('l.updated_by', $admin_id);
        $this->db->where('ct.created_at >=', $month_start);
        $this->db->where('ct.created_at <=', $month_end);
        $this->db->order_by('ct.created_at', 'DESC');

        $query = $this->db->get();
        return json_encode($query->result_array());
    }


